  /// < buffer - RSA OAEP label (not supported at the moment)
  static const int CKMC_PARAM_ED_LABEL = 105;

  /// < integer - function to be used both as Label and MGF hash function
  /// in OAEP padding (see #__ckmc_hash_algo). Currently only #CKMC_HASH_SHA1
  /// and #CKMC_HASH_SHA256 are supported. If not given, the default
  /// #CKMC_HASH_SHA1 is used. (Since 6.0)
  static const int CKMC_PARAM_ED_OAEP_HASH = 106;

  /// < integer - pseudo-random function number (see #ckmc_kdf_prf_e)
  /// (Since 6.0)
  static const int CKMC_PARAM_KDF_PRF = 401;

  /// < integer - length of the derived key in bytes. The value must be one of
  /// {16, 24, 32} (Since 6.0)
  static const int CKMC_PARAM_KDF_LEN = 402;

  /// < integer - KDF mode number (see #ckmc_kbkdf_mode_e) (Since 6.0)
  static const int CKMC_PARAM_KBKDF_MODE = 403;

  /// < buffer - the purpose for the derived key. Conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT (Since 6.0)
  static const int CKMC_PARAM_KBKDF_LABEL = 404;

  /// < buffer - information related to the derived key. Conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT (Since 6.0)
  static const int CKMC_PARAM_KBKDF_CONTEXT = 405;

  /// < buffer - KBKDF fixed input replacing context and label
  /// (Since 6.0). Conflicts with:
  /// - #CKMC_PARAM_KBKDF_LABEL,
  /// - #CKMC_PARAM_KBKDF_CONTEXT,
  /// - #CKMC_PARAM_KBKDF_LLEN,
  /// - #CKMC_PARAM_KBKDF_NO_SEPARATOR
  static const int CKMC_PARAM_KBKDF_FIXED_INPUT = 406;

  /// < integer - specifies location of the counter in KBKDF
  /// (see #ckmc_kbkdf_counter_location_e) (Since 6.0)
  static const int CKMC_PARAM_KBKDF_COUNTER_LOCATION = 407;

  /// < integer - specifies the length of the counter representation in bits
  /// in KBKDF. The value must be one of {8, 16, 24, 32}. If not set, the
  /// default value = 32 will be used. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_RLEN = 408;

  /// < integer - specifies the length of the length suffix representation
  /// in bits in KBKDF. The value must be one of {0, 8, 16, 24, 32}. If set to
  /// 0 the length suffix will be skipped. If not set, the default value = 32
  /// will be used. The length suffix is skipped if
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT is passed and this parameter conflicts
  /// with it. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_LLEN = 409;

  /// < integer - presence of this parameter will skip the zero
  /// octet separator between label and context in KBKDF.
  /// All values are allowed. This parameter conflicts with
  /// #CKMC_PARAM_KBKDF_FIXED_INPUT. (Since 6.0)
  static const int CKMC_PARAM_KBKDF_NO_SEPARATOR = 410;

  /// < buffer - EC public key in DER form (see #ckmc_key_s) (Since 6.0)
  static const int CKMC_PARAM_ECDH_PUBKEY = 411;
}

/// Enumeration for key derivation function pseudo-random function parameter.
///
/// **Since Tizen:**
/// - 6.0
///
/// **See also:**
/// - `ckmc_key_derive()`
/// - `ckmc_param_name_e`
/// @nodoc
abstract class ckmc_kdf_prf {
  /// < HMAC SHA256
  static const int CKMC_KDF_PRF_HMAC_SHA256 = 1;

  /// < HMAC SHA384
  static const int CKMC_KDF_PRF_HMAC_SHA384 = 2;

  /// < HMAC SHA512
  static const int CKMC_KDF_PRF_HMAC_SHA512 = 3;
}

/// Enumeration for key based key derivation function mode.
///
/// **Since Tizen:**
/// - 6.0
///
/// **See also:**
/// - `ckmc_key_derive()`
/// - `ckmc_param_name_e`
/// @nodoc
abstract class ckmc_kbkdf_mode {
  /// < KBKDF counter mode
  static const int CKMC_KBKDF_MODE_COUNTER = 1;
}

/// Enumeration for KBKDF counter location relative to fixed input.
///
/// **Since Tizen:**
/// - 6.0
///
/// **See also:**
/// - `ckmc_key_derive()`
/// - `ckmc_param_name_e`
/// @nodoc
abstract class ckmc_kbkdf_counter_location {
  /// < Counter is located before fixed input
  static const int CKMC_KBKDF_COUNTER_BEFORE_FIXED = 1;

  /// < Counter is located after fixed input
  static const int CKMC_KBKDF_COUNTER_AFTER_FIXED = 2;

  /// < Counter is located in the middle of the fixed input
  /// (between context and label). This setting requires setting
  /// #CKMC_PARAM_KBKDF_LABEL and #CKMC_PARAM_KBKDF_CONTEXT and
  /// conflicts with #CKMC_PARAM_KBKDF_FIXED_INPUT. If this location
  /// is used the separator will be skipped regardless of the
  /// #CKMC_PARAM_KBKDF_NO_SEPARATOR parameter
  static const int CKMC_KBKDF_COUNTER_MIDDLE_FIXED = 3;
}

/// @nodoc
final class __ckmc_param_list extends ffi.Opaque {}

/// Enumeration for crypto algorithm types.
///
/// **Since Tizen:**
/// - 3.0
///
/// **See also:**
/// - `ckmc_param_name_e`
/// @nodoc
abstract class ckmc_algo_type {
  /// < AES-CTR algorithm
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_AES_CTR (mandatory),
  /// - #CKMC_PARAM_ED_IV = 16-byte initialization vector (mandatory)
  /// - #CKMC_PARAM_ED_CTR_LEN = length of counter block in bits
  /// (optional, only 128b is supported at the moment)
  static const int CKMC_ALGO_AES_CTR = 1;

  /// < AES-CBC algorithm
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_AES_CBC (mandatory),
  /// - #CKMC_PARAM_ED_IV = 16-byte initialization vector (mandatory)
  static const int CKMC_ALGO_AES_CBC = 2;

  /// < AES-GCM algorithm
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_AES_GCM (mandatory),
  /// - #CKMC_PARAM_ED_IV = 1 to (2^64-1) bytes long initialization vector.
  /// Note that the backend may impose additional limit on the maximum size
  /// (ckmc_backend_get_max_chunk_size()). Recommended length is 12B (mandatory)
  /// - #CKMC_PARAM_ED_TAG_LEN = GCM tag length in bits. One of
  /// {32, 64, 96, 104, 112, 120, 128} (optional, if not present, the
  /// length 128 is used; since Tizen 5.0, if TrustZone backend is used,
  /// 32 and 64 lengths are not supported)
  /// - #CKMC_PARAM_ED_AAD = additional authentication data. Note that the backend
  /// may impose limit on the maximum size (ckmc_backend_get_max_chunk_size())
  /// (optional)
  static const int CKMC_ALGO_AES_GCM = 3;

  /// < AES-CFB algorithm
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_AES_CFB (mandatory),
  /// - #CKMC_PARAM_ED_IV = 16-byte initialization vector (mandatory)
  static const int CKMC_ALGO_AES_CFB = 4;

  /// < RSA-OAEP algorithm (EME-OAEP as defined in PKCS #1 with MGF1)
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_RSA_OAEP (mandatory),
  /// - #CKMC_PARAM_ED_LABEL = label (encoding parameter) to be associated with
  /// the message (optional, not supported at the moment)
  /// - #CKMC_PARAM_ED_OAEP_HASH = hash algorithm to be used in OAEP padding (see
  /// #__ckmc_hash_algo). (optional)
  static const int CKMC_ALGO_RSA_OAEP = 5;

  /// < Key based key derivation algorithm
  /// Supported parameters:
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_KBKDF (mandatory),
  /// - #CKMC_PARAM_KDF_PRF = pseudo-random function (see #ckmc_kdf_prf_e)
  /// (mandatory),
  /// - #CKMC_PARAM_KBKDF_MODE = KDF mode (see #ckmc_kbkdf_mode_e) (mandatory),
  /// - #CKMC_PARAM_KBKDF_LABEL = the purpose for the derived key (optional),
  /// - #CKMC_PARAM_KBKDF_CONTEXT = information related to the derived key
  /// (optional),
  /// - #CKMC_PARAM_KDF_LEN = length of the derived key (mandatory)
  /// - #CKMC_PARAM_KBKDF_FIXED_INPUT = replacement for context and label (optional),
  /// - #CKMC_PARAM_KBKDF_COUNTER_LOCATION = counter location
  /// (see #ckmc_kbkdf_counter_location_e) (mandatory),
  /// - #CKMC_PARAM_KBKDF_RLEN = length of the counter representation (optional),
  /// - #CKMC_PARAM_KBKDF_LLEN = length of the length suffix representation
  /// (optional),
  /// - #CKMC_PARAM_KBKDF_NO_SEPARATOR = existence of zero separator (optional)
  static const int CKMC_ALGO_KBKDF = 6;

  /// < ECDH shared secret key agreement protocol
  /// Supported parameters (all are required):
  /// - #CKMC_PARAM_ALGO_TYPE = #CKMC_ALGO_ECDH,
  /// - #CKMC_PARAM_ECDH_PUBKEY = peer's public key (see #ckmc_key_s)
  static const int CKMC_ALGO_ECDH = 7;
}

